-- DQ-008: Vital Status Domain---- Purpose:-- Validate the observed values of the vital.status-- variable in the staging layer.---- Expected categories:-- - 0-- - 1---- Expected record counts:-- - 0 = 611-- - 1 = 94-- - Total records = 705---- This validation does not modify the data.SELECT    "vital.status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY "vital.status"ORDER BY quantity DESC;